class Solution {
  private int[] cover;
  private long[] len;
  private long[] xs;

  private void update(int node, int l, int r, int ql, int qr, int v) {
    if (qr <= l || r <= ql) return;
    if (ql <= l && r <= qr) {
      cover[node] += v;
    } else {
      int mid = (l + r) >>> 1;
      update(2 * node, l, mid, ql, qr, v);
      update(2 * node + 1, mid, r, ql, qr, v);
    }
    if (cover[node] > 0) len[node] = xs[r] - xs[l];
    else if (r - l == 1) len[node] = 0;
    else len[node] = len[2 * node] + len[2 * node + 1];
  }

  public double separateSquares(int[][] squares) {
    int n = squares.length;
    long[] all = new long[2 * n];
    for (int i = 0; i < n; i++) {
      all[2 * i] = squares[i][0];
      all[2 * i + 1] = (long) squares[i][0] + squares[i][2];
    }
    java.util.Arrays.sort(all);
    int m = 0;
    for (int i = 0; i < all.length; i++) if (i == 0 || all[i] != all[i - 1]) all[m++] = all[i];
    xs = java.util.Arrays.copyOf(all, m);
    cover = new int[4 * m];
    len = new long[4 * m];
    long[][] events = new long[2 * n][];
    for (int i = 0; i < n; i++) {
      events[2 * i] =
          new long[] {squares[i][1], 1, squares[i][0], (long) squares[i][0] + squares[i][2]};
      events[2 * i + 1] =
          new long[] {
            (long) squares[i][1] + squares[i][2],
            -1,
            squares[i][0],
            (long) squares[i][0] + squares[i][2]
          };
    }
    java.util.Arrays.sort(events, (a, b) -> Long.compare(a[0], b[0]));
    long[] stripY = new long[2 * n], stripW = new long[2 * n], stripDy = new long[2 * n];
    int strips = 0;
    long total = 0, prevY = events[0][0];
    for (long[] e : events) {
      if (e[0] > prevY) {
        stripY[strips] = prevY;
        stripW[strips] = len[1];
        stripDy[strips] = e[0] - prevY;
        total += len[1] * (e[0] - prevY);
        strips++;
        prevY = e[0];
      }
      int l = java.util.Arrays.binarySearch(xs, e[2]), r = java.util.Arrays.binarySearch(xs, e[3]);
      update(1, 0, m - 1, l, r, (int) e[1]);
    }
    double half = total / 2.0;
    long acc = 0;
    for (int i = 0; i < strips; i++) {
      long area = stripW[i] * stripDy[i];
      if (acc + area >= half && stripW[i] > 0) return stripY[i] + (half - acc) / stripW[i];
      acc += area;
    }
    return prevY;
  }
}
